WITH UserReputation AS (SELECT U.Id AS UserId, U.DisplayName, U.Reputation, COUNT(DISTINCT P.Id) AS TotalPosts, COUNT(DISTINCT C.Id) AS TotalComments FROM Users AS U LEFT OUTER JOIN Posts AS P ON U.Id = P.OwnerUserId LEFT OUTER JOIN Comments AS C ON U.Id = C.UserId GROUP BY U.Id, U.DisplayName, U.Reputation), TopUsers AS (SELECT UserId, DisplayName, Reputation, TotalPosts, TotalComments, RANK() OVER (ORDER BY Reputation DESC NULLS FIRST) AS ReputationRank FROM UserReputation), UserBadges AS (SELECT B.UserId, GROUP_CONCAT(B.Name, ', ') AS BadgeNames, COUNT(*) AS BadgeCount FROM Badges AS B GROUP BY B.UserId) SELECT U.DisplayName, U.Reputation, COALESCE(UB.BadgeNames, 'No Badges') AS Badges, COALESCE(UB.BadgeCount, 0) AS TotalBadges, U.TotalPosts, U.TotalComments FROM TopUsers AS U LEFT JOIN UserBadges AS UB ON U.UserId = UB.UserId WHERE U.ReputationRank <= 10 ORDER BY U.Reputation DESC NULLS FIRST LIMIT 10